GimCorpus.put(427,0,[[2,6,"אין מביאין בכורים אחר חנוכה וכו' עד הרי הן חשובין משנה הבאה. א\"א ואיך יתכן זה והלא חנוכה קודם שבט הוא והוא שנה שעברה ונראה לי מפני שהפירות שמתבכרים אחר חנוכה אינן אלא פסולת הפירות והתורה אמרה מראשית ודינם כתאנים סורות ומרוקבות שלא קדשו ואפילו אם יניח אותם לא קדשו ואם הפרישן קודם חנוכה ועברה עליהן חנוכה ירקבו והכי איתא בירושלמי במנחות פרק כל קרבנות ציבור אחר חנוכה לא קדשו:",1,0],[2,9,"אבל מביא מן הגדל בגג. א\"א הוא פסק כר\"ל ולריש לקיש גופיה דוקא בגג מערה וחורבה עבודה ואיני יודע מה ראה לחלק ובמנחות לא חילקו דר\"ל מחייב בכולן ורבי יוחנן פוטר בכולן:",1,0],[2,13,"הקונה אילן בתוך שדה חבירו וכו'. א\"א לא כי אלא מפני שבסתם קנה עמהם קרקע ואם פירש בלא קרקע אינו מביא ואינו דומה לשנים סתם לפי שהשנים ספק אם קנה קרקע אם לא קנה ואם דימה אותו למבריך ברשות לשעה טעה שהרי אף השנים יש לו להעמידם שם כל ימי היותם ואם לא מפני הספק לא היה מביא ולמבריך ברשות אינו דומה כלל שהמבריך עיקרו ברשות עצמו ויניקת ההברכה מעוטה היא וכיון שהוא ברשות אינה אוסרת:",1,0],[2,15,"המוכר שדהו לעכו\"ם וכו'. א\"א אע\"פ שבכרו ברשות העכו\"ם:",1,0],[3,9,"אלו שעם הסלים היו קרבין עולות. א\"א אומר אני מה שבידם ניתנים לכהנים על הפירות הוא אומר במשנה אבל גוזלות אין בידם כי אם אותן שעם הסלים:",1,0],[4,10,"הביא בכוריו ונטמאו בעזרה. א\"א יניחום שם עד שירקבו או עד שיתמסמסו:",1,0],[5,6,"פירות הארץ שיצאו חו\"ל כו'. א\"א פירוש דבר תורה אבל חייבין מדרבנן בשתי חלות:",1,0],[5,8,"ומותרת לזבים ולזבות. א\"א נ\"א אסורה לזבים ולזבות ואין צ\"ל לשאר טמאים:",1,0],[5,10,"ואין צריך להפריש שנייה. א\"א כבר כתבנו מה שנראה לנו מן הגמרא ומהלכות הרב:",1,0],[5,11,"כל המפריש. א\"א כתב רב אחא ז\"ל וקורא לה שם ואומר הרי זו תרומה:",1,0],[6,11,"המערב קמח חטים וכו'. א\"א נראה מן הירושלמי דבעינן שיהא בה דגן כשיעור כרבן שמעון בן גמליאל דהכי פסיק הלכה כוותיה מיהו לא בעינן רוב דגן:",1,0],[6,11,"אפילו היה השאור חטים. א\"א והוא שיהיה השאור מעיסה חייבת:",2,0],[6,19,"אבל העושה עיסה לחלקה בצק פטורה. א\"א נראה מן הגמרא שאף האשה שעשתה עיסתה לחלק חייבת בחלה שמא תמלך לעשותה עיסה מההיא איתתא דאתת ושאלת לרבי מונא בגין דאנא בעיא מעבד עיסתי אטרינא מהו דנסיבנא ותהא פטורה מן החלה א\"ל ולמה לא אתא שאיל לאבוה אמר ליה אסור שמא תמלך לעשות עיסה וממתניתין גופא איכא למשמע נשים שנתנו לנחתום לעשות להן שאור אם אין בכל אחת כשיעור פטורה מן החלה דייקינן הא אשה אחת דומיא דחמש חייבת ואע\"ג דרבי יוחנן הוא דאמר פטורה ר\"ל פליג עליה דאמר דנחתום לאו דוקא וחמש נשים דוקא לענין חלוק הא אשה אחת חייבת בחלוק ומעשה דההיא אתתא מוכח דבכל אשה נמי חיישינן לאימלוכי:",1,0],[7,9,"אבל שני ישראלים וכו' עד מפני שעשו אותה לחלק. א\"א אין דבר זה מחוור ואם עשו אותה לחלק והשלימו מאין לו שהוא פטור ומה בין זה לעושה עיסתו קבין והשיכן או שצרפן בסל שהן חייבין ואע\"פ שראה כן בירושלמי אין השכל נותן לסמוך עליו ועוד דקי\"ל אין דחוי אצל מצות ואחד זה ואחד זה כיון שהשלים עליו חייב:",1,0],[7,10,"היתה העיסה וכו' עד שהשלים כל אחד עיסתו לשיעור של ישראל חייבת וכו'. א\"א דומה דקשיא דידה אדידיה של ישראל אמאי חייבת ושל עכו\"ם אמאי פטורה איפכא מיבעי ליה. ונ\"ל דגמרא דירושלמי בתמיהא קאמר דהכי גרסינן ישראל ועכו\"ם שעשו שני קבין וחלקו והוסיפו זה על שלו וזה על שלו ניחא חלקו של ישראל חייב חלקו של עכו\"ם מהו כלום חלקו של ישראל חייב אלא מפני חלקו של עכו\"ם חלקו של ישראל חייב וחלקו של עכו\"ם פטור משמע דבתמיהא קאמר אלא זה וזה חייב:",1,0],[7,12,"עיסה הטבולה לחלה וכו' עד שלא מן המוקף. א\"א הוא פסק כר\"א וחכמים אוסרין לעשות כן מפני שהוא מטמא חלתה פחות מכביצה ובירושלמי לא הסכימו בסוף כר\"א לעשות מעשה כמותו:",1,0],[8,2,"אימתי מפרישין חלה כשיתן את המים. א\"א אין יפה לעשות כן אלא אם עשה כן הרי קיים ראשית עריסותיכם שהוא נחשבת עיסה ואם חיוב הוא לעשות כן איך יאכל ממנה עראי עד שתגלגל והוא טבל ולשון הירושלמי הטעהו:",1,0],[8,15,"ואין צריך לומר המתארח אצלו. א\"א מן הגמרא נראה המתארח אפילו אצל נחתום אינו צריך להפריש והוא שמתארח אצלו בעיסתו:",1,0],[9,6,"אחד השוחט לאכילת וכו' עכ\"ל. א\"א פירוש דילפינן מכסוי הדם דתניא השוחט וצריך לדם חייב לכסות כיצד יעשה נוחרו או עוקרו:",1,0],[10,7,"ונוהג בכלאים ובכוי. א\"א נראה לי לענין ראשית הגז כוי הבא מן חיה ובהמה פטור מפני שצמרו קשה:",1,0],[11,25,"זכר ונקבה או שני זכרים ונקבה וכו'. א\"א טעה בזה שזה חייב מפני שהוא ספק ספיקא ובאיש אחד חייב שאין ספק ספיקא פוטר אותו אבל בשתי נשים של שני אנשים אחת בכרה ואחת לא בכרה זהו שאמרו בתוספתא שפטור:",1,0],[11,30,"ילדו שני זכרים ונקבה זה שלא בכרה. א\"א כל זה שבוש אלא שניהן פטורין כמו שכתבתי למעלה:",1,0],[12,1,"ואם לא רצה לפדותו מצות עשה לעורפו. א\"א בחיי ראשי אין זה מן הפלפול ולא מן הדעת המיושבת שיחשוב זה במצות עשה אע\"פ שאמרו מצות פדייה קודמת למצות עריפה לא שתחשב מצוה אבל היא עבירה ומזיק נקרא ומפסיד ממונו של כהן ומפני שאמר מצות פדייה אמר מצות עריפה:",1,0],[12,4,"פטר חמור אסור בהנאה וכו'. א\"א אם דמיו אסורין למה לא יתנם לכהן ויהנה בהן שהרי פודין פטר חמור בשוויו וכי מאיסורי הנאה שתופסין את דמיהן הוא זה:",1,0],[12,12,"אבל אם היו דמיו וכו'. א\"א והשה עצמו צריך שישוה ג' זוזים בבא לימלך ואם פדה מעצמו אפילו בפטרוזא בת דנקא יצא:",1,0],[12,21,"ילדו שתי נקבות וכו' עד ואינו צריך להפריש טלה לעצמו. א\"א יש כאן שיבושין והספיקות שמא הזכר יצא אחרי הנקבה:",1,0]]);
